window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[249]={"id":"249","numero":249,"titre":"Modifications thérapeutiques du mode de vie (alimentation et activité physique)","objectifs":[{"id":"249-1","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évaluer le comportement alimentaire","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">modifications thérapeutiques du mode de vie</span></strong> (<span class=\"kw-def\">MTMV</span>) portent avant tout sur l'<span class=\"kw-def\">alimentation</span> et l'<span class=\"kw-def\">activité physique</span>, mais aussi sur l'observance des traitements, la gestion des conduites à risque (<span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>), le <span class=\"kw-clinique\">sommeil</span> et la socialisation. Le terme « <span class=\"kw-def\">règles hygiéno-diététiques</span> » est <strong>à abandonner</strong>.</p>\n<h4 class=\"kw-def\">Physiologie : régulation du comportement alimentaire</h4>\n<p>L'alimentation repose sur le respect des <strong><span class=\"kw-def\">signaux intéroceptifs</span></strong> de faim et de rassasiement :</p>\n<ul>\n<li><strong><span class=\"kw-def\">Faim</span></strong> = <span class=\"kw-clinique\">sensation physique</span> (contraction de la musculature gastrique), déclenchée par l'<span class=\"kw-def\">hypothalamus</span>.</li>\n<li><strong><span class=\"kw-def\">Rassasiement</span></strong> = <span class=\"kw-clinique\">extinction du signal de faim</span>, sans nouveau signal physique (tension gastrique si l'on dépasse ce <span class=\"kw-def\">stade</span>).</li>\n<li><strong><span class=\"kw-def\">Satiété</span></strong> = <span class=\"kw-clinique\">absence de faim</span>, période entre le rassasiement et la faim suivante.</li>\n</ul>\n<p>Ces signaux sont perturbés par l'<span class=\"kw-etio\">environnement familial et culturel</span> et par l'<span class=\"kw-etio\">inflammation</span> (<span class=\"kw-bio\">IL-1</span>, <span class=\"kw-bio\">TNF-α</span>).</p>\n<h4 class=\"kw-def\">Anomalies de la relation à l'alimentation</h4>\n<ul>\n<li><span class=\"kw-clinique\">Tachyphagie</span> (manger vite), <span class=\"kw-clinique\">hyperphagie prandiale</span>, <span class=\"kw-clinique\">prises extraprandiales</span> → situations d'<span class=\"kw-etio\">excès pondéral</span>.</li>\n<li><strong><span class=\"kw-clinique\">Impulsivité alimentaire</span></strong>.</li>\n<li><strong><span class=\"kw-def\">Restriction cognitive</span></strong> = contrôle mental des prises se substituant aux signaux physiologiques.</li>\n</ul>\n<h4 class=\"kw-def\">Démarche d'évaluation</h4>\n<ul>\n<li>Rechercher un <strong><span class=\"kw-etio\">trouble de l'humeur</span></strong> (dépression).</li>\n<li>Rechercher une <strong><span class=\"kw-etio\">pathologie chronique</span></strong> : maladie <span class=\"kw-etio\">inflammatoire</span>, <span class=\"kw-etio\">cancer</span>.</li>\n<li>Faire tenir un <strong><span class=\"kw-def\">carnet alimentaire</span></strong> pendant <span class=\"kw-chiffre\">une semaine</span> (optionnel).</li>\n</ul>","frequence":0},{"id":"249-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître les effets positifs de l’activité physique dans les maladies chroniques et savoir les expliquer au patient","contenu":"<p>L'<strong><span class=\"kw-def\">activité physique</span></strong> (<span class=\"kw-def\">AP</span>) régulière améliore le <span class=\"kw-clinique\">pronostic</span> et la <span class=\"kw-clinique\">qualité de vie</span> dans la quasi-totalité des maladies chroniques. Ces bénéfices sont à expliquer au patient comme un <strong>traitement à part entière</strong>.</p>\n<table >\n<thead><tr><th>Pathologie</th><th>Effets positifs de l'activité physique</th></tr></thead>\n<tbody>\n<tr><td><strong><span class=\"kw-etio\">Cancer</span></strong></td><td>↓ <span class=\"kw-clinique\">mortalité</span> et <span class=\"kw-clinique\">récidive</span> ; ↓ <span class=\"kw-clinique\">fatigue</span> et meilleure tolérance aux traitements ; renforce l'<span class=\"kw-bio\">immunité</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Obésité</span></strong></td><td>↓ modeste du <span class=\"kw-clinique\">poids</span> et de la <span class=\"kw-clinique\">masse grasse</span> (qq kg), ↓ <span class=\"kw-clinique\">graisse abdominale viscérale</span> ; amélioration métabolique ; ↓ <span class=\"kw-clinique\">risque de reprise de poids</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Diabète de type 2</span></strong></td><td>↓ <span class=\"kw-clinique\">mortalité</span> ; amélioration <span class=\"kw-bio\">HbA1c</span> et profil lipidique ; ↓ <span class=\"kw-clinique\">périmètre abdominal</span> ; limite la perte de <span class=\"kw-clinique\">masse musculaire</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">HTA</span></strong></td><td>↓ <span class=\"kw-clinique\">risque de progression cardiovasculaire</span> ; ↓ l'augmentation de la <span class=\"kw-bio\">PA</span> avec le temps</td></tr>\n<tr><td><strong><span class=\"kw-etio\">Cardiopathie, IC, AOMI</span></strong></td><td>amélioration du <span class=\"kw-clinique\">pronostic fonctionnel et vital</span> ; ↓ <span class=\"kw-bio\">PA</span> ; amélioration de la <span class=\"kw-clinique\">fonction endothéliale</span> ; développement de <span class=\"kw-clinique\">néovaisseaux</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">BPCO</span></strong></td><td>amélioration des <span class=\"kw-clinique\">capacités physiques</span>, de la <span class=\"kw-clinique\">dyspnée</span> et de la tolérance à l'effort ; ↓ <span class=\"kw-clinique\">anxiété</span> (pas de modification de la fonction pulmonaire chez l'adulte)</td></tr>\n<tr><td><strong><span class=\"kw-etio\">Rhumatisme, arthrose</span></strong></td><td>↓ <span class=\"kw-clinique\">douleur</span> ; amélioration des <span class=\"kw-clinique\">capacités fonctionnelles</span> et de la qualité de vie</td></tr>\n<tr><td><strong><span class=\"kw-etio\">Dépression, anxiété</span></strong></td><td>↓ <span class=\"kw-clinique\">signes anxieux et dépressifs</span> ; amélioration de l'<span class=\"kw-clinique\">humeur</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">TDAH</span></strong></td><td>amélioration des <span class=\"kw-clinique\">fonctions cognitives</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Pathologies neurologiques</span></strong><br>(démence, schizophrénie, SEP, Parkinson, <span class=\"kw-alerte\">AVC</span>)</td><td>amélioration des <span class=\"kw-clinique\">fonctions cognitives</span> ; amélioration de la <span class=\"kw-clinique\">marche</span>, de la <span class=\"kw-clinique\">force musculaire</span> et de l'<span class=\"kw-clinique\">équilibre</span> (SEP, Parkinson, <span class=\"kw-alerte\">AVC</span>)</td></tr>\n</tbody>\n</table>","frequence":1},{"id":"249-3","rang":"B","rubrique":"Prise en charge","titre":"Savoir comment renforcer les compétences psycho-sociales","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">compétences psychosociales</span></strong> (<span class=\"kw-def\">CPS</span>) sont définies par l'<span class=\"kw-def\">OMS</span> comme un <span class=\"kw-def\">ensemble de capacités psychologiques</span> (cognitives, émotionnelles et sociales) permettant d'augmenter l'<strong><span class=\"kw-def\">autonomisation</span></strong> (<span class=\"kw-def\">empowerment</span>), de maintenir un <span class=\"kw-clinique\">bien-être psychique</span> et de développer des interactions constructives.</p>\n<div class=\"callout callout-info\">Renforcer <span class=\"kw-clinique\">les</span> CPS <strong>favorise les changements de comportement et leur maintien dans le temps</strong>, en particulier dans les <span class=\"kw-etio\">populations défavorisées</span>.</div>\n<p>Le <strong>soignant</strong> a un rôle clé dans le développement de l'<span class=\"kw-clinique\">estime de soi</span> : <span class=\"kw-clinique\">bienveillance</span>, <span class=\"kw-clinique\">valorisation</span>, <span class=\"kw-clinique\">déculpabilisation</span> ; orientation possible vers <span class=\"kw-clinique\">art-thérapie</span> ou <span class=\"kw-clinique\">bénévolat</span>.</p>\n<h4 class=\"kw-def\">Compétences sociales</h4>\n<ul>\n<li><span class=\"kw-clinique\">Communiquer</span> de façon constructive : écoute empathique, communication efficace.</li>\n<li>Développer des <span class=\"kw-clinique\">relations constructives</span> : liens sociaux, comportements prosociaux.</li>\n<li><span class=\"kw-clinique\">Résoudre des difficultés</span> : demander de l'aide, assertivité, refus, résolution de conflits.</li>\n</ul>\n<h4 class=\"kw-def\">Compétences cognitives</h4>\n<ul>\n<li><span class=\"kw-clinique\">Conscience et connaissance de soi</span> ; pensée critique, auto-évaluation positive.</li>\n<li><span class=\"kw-clinique\">Maîtrise de soi</span> : gérer ses impulsions, atteindre ses buts.</li>\n<li><span class=\"kw-clinique\">Décisions constructives</span> : choix responsables, résolution créative de problèmes.</li>\n</ul>\n<h4 class=\"kw-def\">Compétences émotionnelles</h4>\n<ul>\n<li><span class=\"kw-clinique\">Conscience de ses émotions et de son stress</span> : <span class=\"kw-clinique\">les</span> identifier et les comprendre.</li>\n<li><span class=\"kw-clinique\">Réguler ses émotions</span> : <span class=\"kw-clinique\">les</span> exprimer de façon positive, les gérer.</li>\n<li><span class=\"kw-clinique\">Gérer son stress</span> : faire face à l'adversité (<span class=\"kw-def\">coping</span>).</li>\n</ul>","frequence":0},{"id":"249-4","rang":"B","rubrique":"Prise en charge","titre":"Savoir déterminer avec le patient des objectifs d’éducation thérapeutique","contenu":"<p>L'<strong><span class=\"kw-def\">éducation thérapeutique</span></strong> (<span class=\"kw-def\">ETP</span>) vise à déterminer <strong>avec le patient</strong> des <strong><span class=\"kw-def\">objectifs éducatifs</span></strong>, dans une <strong>mise en place progressive</strong>. Le <strong><span class=\"kw-clinique\">suivi</span></strong> est <strong>indispensable</strong>.</p>\n<h4 class=\"kw-def\">Posture éducative du soignant</h4>\n<p><span class=\"kw-clinique\">Écoute</span> et <span class=\"kw-clinique\">accompagnement cognitif et psychosocial</span>, fondés sur :</p>\n<ul>\n<li>Un <strong><span class=\"kw-def\">processus d'autodétermination</span></strong> du projet de changement par le patient.</li>\n<li><strong><span class=\"kw-clinique\">Donner du sens</span></strong> au projet (enjeux de santé) <strong>sans angoisser</strong>.</li>\n<li>Recourir aux <strong><span class=\"kw-def\">entretiens motivationnels</span></strong>, favoriser la <span class=\"kw-clinique\">réflexivité</span>.</li>\n<li><span class=\"kw-clinique\">Interroger les représentations</span> du patient, puis <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">relativiser</span>.</li>\n<li>Maintenir la <span class=\"kw-clinique\">relation de confiance</span> et de <span class=\"kw-clinique\">dialogue</span>.</li>\n</ul>\n<h4 class=\"kw-def\">Mesures supplémentaires favorisant le changement</h4>\n<ul>\n<li>Correction des <strong><span class=\"kw-clinique\">troubles du sommeil</span></strong>.</li>\n<li>Traitement des <strong><span class=\"kw-etio\">troubles de l'humeur</span></strong>.</li>\n<li><span class=\"kw-clinique\">Expression des difficultés de vie</span>.</li>\n<li>Intégration dans un <strong><span class=\"kw-def\">groupe d'éducation thérapeutique</span></strong>.</li>\n</ul>","frequence":0},{"id":"249-5","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire une alimentation adaptée dans les principales maladies chroniques","contenu":"<p>La <strong><span class=\"kw-def\">prescription d'une alimentation thérapeutique</span></strong> est, en <span class=\"kw-alerte\">hospitalisation</span>, une <strong>prescription médicale écrite obl<span class=\"kw-chiffre\">iga</span>toire</strong> : c'est un <span class=\"kw-def\">acte médico-légal</span> engageant la <span class=\"kw-clinique\">responsabilité du médecin</span>. Elle précise :</p>\n<ul>\n<li>Le <span class=\"kw-clinique\">type d'alimentation</span>, la <span class=\"kw-clinique\">texture</span>, le nombre de <span class=\"kw-clinique\">collations</span>.</li>\n<li>Le type de <strong><span class=\"kw-def\">compléments nutritionnels oraux</span></strong> (<span class=\"kw-def\">CNO</span>) et leurs horaires.</li>\n<li>L'<span class=\"kw-clinique\">aide aux repas</span>.</li>\n<li><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-clinique\">mesures posturales</span></strong> de prévention des <span class=\"kw-alerte\">fausses routes</span>.</li>\n</ul>\n<h4 class=\"kw-def\">Recommandations du PNNS selon la maladie chronique</h4>\n<table >\n<thead><tr><th>Pathologie</th><th>Alimentation recommandée</th></tr></thead>\n<tbody>\n<tr><td><strong><span class=\"kw-etio\">Obésité</span></strong></td><td><span class=\"kw-clinique\">stabilisation pondérale</span>, voire perte de <span class=\"kw-chiffre\">5–10 % du poids</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Diabète</span></strong></td><td>alimentation <span class=\"kw-clinique\">standard</span> ; apport régulier en <span class=\"kw-clinique\">glucides</span> à chaque repas si traitement <span class=\"kw-ttt\">hypoglycémiant</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Insuffisance rénale chronique</span></strong></td><td>adapter <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">apports protidiques</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Maladie inflammatoire chronique</span></strong> sous <span class=\"kw-ttt\">corticoïdes</span></td><td>alimentation <span class=\"kw-clinique\">équilibrée</span> (ni pauvre en sel, ni pauvre en sucre)</td></tr>\n<tr><td>Pas de recommandation spécifique</td><td>apports lipidiques <span class=\"kw-chiffre\">&lt; 35 %</span> des apports énergétiques (sauf <span class=\"kw-etio\">hypertriglycéridémie majeure primitive</span> et épanchement chyleux)</td></tr>\n</tbody>\n</table>\n<h4 class=\"kw-def\">Conseil diététique = <span class=\"kw-def\">éducation thérapeutique</span></h4>\n<ul>\n<li><strong>Non standardisé</strong> : <span class=\"kw-clinique\">personnalisé</span>, objectifs concrets.</li>\n<li>Accompagner la mise en œuvre et le maintien des comportements ; accepter le <span class=\"kw-clinique\">rythme de changement</span>.</li>\n<li>Respecter le <strong>plaisir de manger</strong> ; +/- <span class=\"kw-clinique\">diététicien</span>, ateliers cuisine.</li>\n<li>Objectifs : <span class=\"kw-clinique\">répartition des repas</span>, <span class=\"kw-clinique\">vitesse d'ingestion</span>, identification des <span class=\"kw-clinique\">signaux de faim et de rassasiement</span>, <span class=\"kw-clinique\">diversification</span>, prévention des <span class=\"kw-alerte\">hypoglycémies</span> (équivalence glucidique chez le diabétique).</li>\n</ul>","frequence":2},{"id":"249-6","rang":"B","rubrique":"Prise en charge","titre":"Savoir promouvoir l’activité physique","contenu":"<p>La <strong><span class=\"kw-def\">promotion de l'activité physique</span></strong> repose sur des conseils de <strong>progression individuelle</strong>, par étapes et à long terme. L'AP est un <span class=\"kw-clinique\">exutoire des tensions</span>, un facteur de <span class=\"kw-clinique\">lien social</span>, de <span class=\"kw-clinique\">reprise de conscience du corps</span> et d'amélioration du <span class=\"kw-clinique\">sommeil</span>.</p>\n<h4 class=\"kw-def\">1. Évaluer le niveau habituel d'activité et de <span class=\"kw-etio\">sédentarité</span></h4>\n<ul>\n<li>AP <span class=\"kw-clinique\">quotidienne</span>, <span class=\"kw-clinique\">professionnelle</span>, de <span class=\"kw-clinique\">loisir</span> : durée, intensité, fréquence, contexte.</li>\n<li>Niveau de <strong><span class=\"kw-def\">sédentarité</span></strong>, activités antérieures, centres d'intérêt.</li>\n</ul>\n<h4 class=\"kw-def\">2. Définir <span class=\"kw-clinique\">les</span> objectifs avec le patient</h4>\n<ul>\n<li>Proposer des activités d'<span class=\"kw-clinique\">intensité plus élevée</span> sur une base individuelle, dans un cadre récréatif ou de loisir.</li>\n<li>Donner des <span class=\"kw-clinique\">repères quantitatifs</span> et des conditions d'exercice sécurisées.</li>\n<li>Évaluer <span class=\"kw-clinique\">les</span> effets et adapter les objectifs ; <span class=\"kw-clinique\">accompagnement</span>.</li>\n</ul>\n<h4 class=\"kw-def\">3. Individualiser et organiser le <span class=\"kw-def\">suivi</span></h4>\n<ul>\n<li>Reprise <strong>très progressive</strong> ; limiter le temps de <span class=\"kw-clinique\">sédentarité</span>.</li>\n<li><span class=\"kw-clinique\">Suivi indispensable</span> : évaluer effets et difficultés.</li>\n<li>Moyen objectif de mesure de l'AP : <strong><span class=\"kw-def\">podomètre</span></strong>.</li>\n</ul>\n<h4 class=\"kw-def\">Recommandations selon la pathologie</h4>\n<table >\n<thead><tr><th>Pathologie</th><th>Endurance (aérobie) ↑ <span class=\"kw-bio\">VO2max</span></th><th>Renforcement musculaire ↑ force</th></tr></thead>\n<tbody>\n<tr><td><strong><span class=\"kw-etio\">Cardiovasculaires</span></strong></td><td><span class=\"kw-chiffre\">+</span></td><td><span class=\"kw-chiffre\">+</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">BPCO</span></strong></td><td><span class=\"kw-chiffre\">+</span></td><td><span class=\"kw-chiffre\">+</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Obésité</span></strong></td><td><span class=\"kw-chiffre\">++</span></td><td><span class=\"kw-chiffre\">+</span></td></tr>\n<tr><td><strong><span class=\"kw-etio\">Diabète de type 2</span></strong></td><td><span class=\"kw-chiffre\">++</span></td><td><span class=\"kw-chiffre\">+</span></td></tr>\n</tbody>\n</table>","frequence":2},{"id":"249-7","rang":"B","rubrique":"Prise en charge","titre":"Savoir orienter vers la pratique d’une activité physique adaptée o N 250. Dénutrition chez l’adulte et l’enfant.","contenu":"<p>Orienter vers une <strong><span class=\"kw-def\">activité physique adaptée</span></strong> (<span class=\"kw-def\">APA</span>) repose sur une <strong><span class=\"kw-def\">prescription</span></strong> sur <span class=\"kw-clinique\">ordonnance</span> ou <span class=\"kw-clinique\">carnet de liaison</span> pour <span class=\"kw-clinique\">les</span> patients en <strong><span class=\"kw-def\">ALD</span></strong> (<span class=\"kw-def\">affection de longue durée</span>).</p>\n<ul>\n<li>Adresser vers des <strong><span class=\"kw-def\">professionnels de l'AP adaptée</span></strong> : <strong><span class=\"kw-def\">enseignant en APA</span></strong> (<span class=\"kw-clinique\">formation spécifique</span>), qui aide à l'<span class=\"kw-clinique\">initiation</span> ou à la <span class=\"kw-clinique\">reprise</span> d'une activité physique.</li>\n<li>Signaler <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-etio\">limitations liées aux comorbidités</span></strong> ; +/- <span class=\"kw-clinique\">évaluation spécialisée</span> par un <span class=\"kw-clinique\">cardiologue</span>.</li>\n<li>Prise en charge possible par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">collectivités</span> et les <span class=\"kw-clinique\">mutuelles</span>.</li>\n</ul>\n<div class=\"callout callout-info\"><strong><span class=\"kw-def\">Prescri'mouv</span></strong> : <span class=\"kw-clinique\">programmes de reprise</span> d'une <span class=\"kw-ttt\">APA</span> pour <span class=\"kw-clinique\">les</span> patients atteints de <span class=\"kw-etio\">pathologies chroniques</span>. Pour les personnes <span class=\"kw-etio\">socialement défavorisées</span>, certaines villes ou mutuelles prennent en charge les coûts d'inscription.</div>","frequence":0},{"id":"249-8","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la dénutrition","contenu":"<p>La <strong><span class=\"kw-def\">dénutrition</span></strong> est un <strong><span class=\"kw-def\">enjeu de santé publique</span></strong>. Son <span class=\"kw-clinique\">dépistage n'est pas systématique</span> : <span class=\"kw-clinique\">les</span> chiffres de <span class=\"kw-def\">prévalence</span> proviennent d'extrapolations. Elle touche <strong>tous les âges</strong>, surtout aux <strong><span class=\"kw-clinique\">deux extrêmes de la vie</span></strong>.</p>\n<div class=\"callout callout-info\">Dans <span class=\"kw-clinique\">les</span> pays d'abondance, la dénutrition touche <strong>très majoritairement des <span class=\"kw-clinique\">individus malades</span></strong> (pathologie <span class=\"kw-etio\">organique</span> ou <span class=\"kw-etio\">psychiatrique</span>) : son <span class=\"kw-def\">épidémiologie</span> suit celle des <span class=\"kw-etio\">maladies graves et/ou chroniques</span>.</div>\n<h4 class=\"kw-def\">Chiffres clés (France)</h4>\n<ul>\n<li><strong>Admission hospitalière</strong> : <span class=\"kw-chiffre\">≈ 50 %</span> des sujets âgés (<span class=\"kw-chiffre\">&gt; 70 ans</span>), <span class=\"kw-chiffre\">≈ 30 %</span> des adultes, <span class=\"kw-chiffre\">≈ 10 %</span> des enfants ; fréquence qui <strong>augmente avec la <span class=\"kw-clinique\">durée de séjour</span></strong>.</li>\n<li><strong>À domicile</strong> : <span class=\"kw-chiffre\">4 %</span> des <span class=\"kw-chiffre\">70–79 ans</span>, <span class=\"kw-chiffre\">10 %</span> après <span class=\"kw-chiffre\">80 ans</span>.</li>\n<li><span class=\"kw-def\">Prévalence</span> globale : <strong><span class=\"kw-chiffre\">≈ 3 millions</span></strong> d'individus en France.</li>\n<li><span class=\"kw-def\">Incidence</span> en milieu hospitalier : <span class=\"kw-chiffre\">≈ 30 %</span> ; <span class=\"kw-def\">dépistage</span> recommandé dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 premières heures</span>.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-9","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs de risque de la dénutrition chez l’adulte","contenu":"<p>Il n'y a <strong>pas de dénutrition sans étiologie</strong> : on parle de <strong><span class=\"kw-def\">situations à risque</span></strong> = <strong>toutes <span class=\"kw-clinique\">les</span> pathologies sévères ou chroniques</strong> où les apports ne couvrent pas les besoins. Le déficit apparaît quand les <span class=\"kw-def\">entrées</span> deviennent chroniquement inférieures aux <span class=\"kw-def\">sorties</span>.</p>\n<h4 class=\"kw-def\">Quatre mécanismes</h4>\n<ul>\n<li><strong>↓ des entrées</strong> : <span class=\"kw-clinique\">baisse des ingesta</span> (de très loin la plus fréquente) ou <span class=\"kw-etio\">malabsorption</span> digestive.</li>\n<li><strong>↑ des sorties</strong> : <span class=\"kw-etio\">augmentation des dépenses énergétiques</span> (rare), ou <span class=\"kw-etio\">pertes de substrats</span> — digestives (<span class=\"kw-clinique\">entéropathies exsudatives</span>), urinaires (<span class=\"kw-clinique\">glycosurie</span>, <span class=\"kw-clinique\">syndrome néphrotique</span>), cutanées (<span class=\"kw-clinique\">brûlures</span> étendues).</li>\n</ul>\n<h4 class=\"kw-def\">Quatre grandes causes</h4>\n<ul>\n<li><strong><span class=\"kw-etio\">Organiques</span></strong> : <span class=\"kw-etio\">cancers</span> (surtout digestifs/ORL), <span class=\"kw-etio\">malabsorption</span> (<span class=\"kw-etio\">maladie cœliaque</span>, Crohn, insuffisance pancréatique), <span class=\"kw-etio\">MICI</span>, maladies <span class=\"kw-etio\">neurologiques</span> (troubles de déglutition), <span class=\"kw-etio\">infections chroniques</span> (<span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">VIH</span>), <span class=\"kw-etio\">hyperthyroïdie</span>, défaillances d'organe (<span class=\"kw-etio\">insuffisance cardiaque</span>, rénale).</li>\n<li><strong><span class=\"kw-etio\">Psychiatriques</span></strong> : <span class=\"kw-etio\">anorexie mentale</span> et <span class=\"kw-bio\">TCA</span>, <span class=\"kw-etio\">syndrome dépressif</span>.</li>\n<li><strong><span class=\"kw-etio\">Socio-environnementales</span></strong> : <span class=\"kw-etio\">précarité</span>, <span class=\"kw-def\">isolement</span>, <span class=\"kw-etio\">alcoolisme</span>.</li>\n<li><strong><span class=\"kw-etio\">Iatrogènes</span></strong> : médicaments (sujet âgé polymédiqué), <span class=\"kw-etio\">chimiothérapie/radiothérapie</span> (dysgueusie, mucite), régimes trop stricts, <span class=\"kw-etio\">jeûne iatrogène</span>.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-10","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs de risque de la dénutrition chez l’enfant","contenu":"<p>Chez l'enfant, la <strong><span class=\"kw-def\">croissance</span></strong> majore <span class=\"kw-clinique\">les</span> besoins et la <strong><span class=\"kw-clinique\">vulnérabilité</span></strong> à la dénutrition : son coût énergétique représente <span class=\"kw-chiffre\">20–25 %</span> des besoins durant les <span class=\"kw-chiffre\">6 premiers mois</span> de vie. La dénutrition y est précédée d'un <strong><span class=\"kw-clinique\">arrêt de la croissance staturale et/ou pondérale</span></strong> (<span class=\"kw-clinique\">retard staturo-pondéral</span>).</p>\n<p><span class=\"kw-clinique\">Les</span> <strong>mécanismes</strong> sont communs à l'adulte (↓ ingesta, malabsorption, pertes, hypercatabolisme), avec des <strong>causes pédiatriques</strong> particulières :</p>\n<ul>\n<li><strong><span class=\"kw-etio\">Augmentation des besoins</span></strong> : <span class=\"kw-etio\">prématurité</span> / <span class=\"kw-etio\">faible poids de naissance</span>, croissance rapide.</li>\n<li><strong><span class=\"kw-etio\">Malabsorption</span></strong> : <span class=\"kw-etio\">maladie cœliaque</span>, <span class=\"kw-etio\">mucoviscidose</span>, <span class=\"kw-etio\">MICI</span>.</li>\n<li><strong><span class=\"kw-etio\">Hypercatabolisme</span></strong> : <span class=\"kw-etio\">cardiopathies congénitales</span>, <span class=\"kw-etio\">infections chroniques</span>, <span class=\"kw-etio\">cancers</span>.</li>\n<li><strong>↓ des apports</strong> : maladies <span class=\"kw-etio\">neurologiques</span> (<span class=\"kw-clinique\">troubles de la déglutition</span>, <span class=\"kw-alerte\">fausses routes</span>), <span class=\"kw-etio\">anorexie mentale</span> de l'adolescent.</li>\n<li><strong><span class=\"kw-etio\">Socio-environnementales</span></strong> : <span class=\"kw-etio\">précarité</span>, <span class=\"kw-etio\">négligence</span>.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-11","rang":"A","rubrique":"Pronostic","titre":"Connaître les conséquences de la dénutrition","contenu":"<p>La dénutrition, surtout par <strong><span class=\"kw-def\">hypercatabolisme protéique</span></strong>, entraîne une <strong><span class=\"kw-def\">sarcopénie</span></strong> (↓ <span class=\"kw-clinique\">masse</span> + force/performance musculaire) et de multiples défaillances. C'est un <strong>facteur indépendant de morbi-<span class=\"kw-def\">mortalité</span></strong>.</p>\n<table >\n<thead><tr><th>Cible</th><th>Conséquences</th></tr></thead>\n<tbody>\n<tr><td><strong>Muscle squelettique</strong></td><td><span class=\"kw-clinique\">sarcopénie</span> : perte d'autonomie, ↓ vitesse de marche et de préhension, <span class=\"kw-alerte\">chutes</span> ; décès quand <span class=\"kw-chiffre\">≈ 50 %</span> de la <span class=\"kw-clinique\">masse</span> musculaire est perdue</td></tr>\n<tr><td><strong>Muscles respiratoires</strong></td><td><span class=\"kw-alerte\">infections pulmonaires</span> ; aggravation d'une <span class=\"kw-ci\">insuffisance respiratoire</span> ; <span class=\"kw-ttt\">sevrage</span> ventilatoire difficile</td></tr>\n<tr><td><strong>Muscle cardiaque</strong></td><td>↓ <span class=\"kw-clinique\">masse</span> et contractilité ; aggrave l'<span class=\"kw-clinique\">insuffisance cardiaque</span> ; <span class=\"kw-alerte\">OAP</span> si perfusion excessive</td></tr>\n<tr><td><strong>Muscles lisses digestifs</strong></td><td><span class=\"kw-clinique\">RGO</span>, retard de vidange gastrique, <span class=\"kw-clinique\">constipation</span></td></tr>\n<tr><td><strong>Tube digestif</strong></td><td>atrophie entérocytaire → ↓ absorption + <span class=\"kw-alerte\">translocation bactérienne</span> (<span class=\"kw-alerte\">sepsis</span> à BGN), lâchage de sutures</td></tr>\n<tr><td><strong>Immunité</strong></td><td><span class=\"kw-bio\">lymphopénie</span> (<span class=\"kw-chiffre\">&lt; 1500/mm³</span>), immunodépression ; <strong>risque <span class=\"kw-etio\">infectieux</span> ×5</strong></td></tr>\n<tr><td><strong>Peau / cicatrisation</strong></td><td><span class=\"kw-alerte\">escarres</span> (risque ×4), retard de cicatrisation, lâchage de sutures</td></tr>\n<tr><td><strong>Neuro-cognitif</strong></td><td>enfant : retard des acquisitions ; sujet âgé : <span class=\"kw-clinique\">apathie</span>, <span class=\"kw-clinique\">dépression</span>, <span class=\"kw-alerte\">syndrome de glissement</span></td></tr>\n<tr><td><strong>Os</strong></td><td><span class=\"kw-clinique\">ostéoporose</span> (adulte), retard de croissance staturale (enfant)</td></tr>\n</tbody>\n</table>\n<div class=\"callout callout-info\">Conséquences pronostiques : ↑ <span class=\"kw-clinique\">morbi-mortalité</span>, ↑ <span class=\"kw-clinique\">durée de séjour</span>, ↑ nombre de prescriptions (antibiotiques) et du <span class=\"kw-clinique\">coût</span> de l'<span class=\"kw-alerte\">hospitalisation</span>.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","contenu":"<p>Diagnostic selon la <strong><span class=\"kw-def\">HAS 2019</span></strong>, exclusivement <strong>clinique</strong> : il associe <strong><span class=\"kw-chiffre\">≥ 1</span> critère phénotypique</strong> ET <strong>≥ 1 critère étiologique</strong>. Chez l'enfant, on utilise <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">courbes IOTF</span></strong> (corpulence/IMC selon le sexe et l'âge, carnet de santé).</p>\n<h4 class=\"kw-def\">Critères phénotypiques (1 seul suffit)</h4>\n<ul>\n<li>Perte de poids <span class=\"kw-chiffre\">≥ 5 % en 1 mois</span>, <span class=\"kw-chiffre\">≥ 10 % en 6 mois</span>, ou <span class=\"kw-chiffre\">≥ 10 %</span> <span class=\"kw-bio\">vs</span> poids habituel avant la maladie.</li>\n<li><span class=\"kw-chiffre\">IMC &lt; courbe IOTF 18,5</span>.</li>\n<li><span class=\"kw-clinique\">Stagnation pondérale</span> aboutissant à un poids <span class=\"kw-chiffre\">≥ 2 couloirs</span> sous le couloir habituel.</li>\n<li><span class=\"kw-ttt\">Réduction</span> de la <span class=\"kw-clinique\">masse et/ou de la fonction musculaire</span>.</li>\n</ul>\n<h4 class=\"kw-def\">Critères étiologiques (1 seul suffit, communs à tous <span class=\"kw-clinique\">les</span> âges)</h4>\n<ul>\n<li><span class=\"kw-clinique\">Réduction de la prise alimentaire</span> <span class=\"kw-chiffre\">≥ 50 % &gt; 1 semaine</span>, ou toute <span class=\"kw-ttt\">réduction</span> <span class=\"kw-chiffre\">&gt; 2 semaines</span>.</li>\n<li><span class=\"kw-etio\">Malabsorption</span> / maldigestion.</li>\n<li><span class=\"kw-etio\">Situation d'agression</span> : pathologie aiguë, chronique évolutive ou maligne évolutive.</li>\n</ul>\n<h4 class=\"kw-def\">Gradation</h4>\n<table >\n<thead><tr><th>Dénutrition modérée</th><th>Dénutrition sévère</th></tr></thead>\n<tbody>\n<tr><td>Perte de poids <span class=\"kw-chiffre\">≥ 5 % et ≤ 10 %</span> /<span class=\"kw-chiffre\"> 1 mois</span> ; <span class=\"kw-chiffre\">≥ 10 % et ≤ 15 %</span> /<span class=\"kw-chiffre\"> 6 mois</span></td><td>Perte de poids <span class=\"kw-chiffre\">&gt; 10 %</span> /<span class=\"kw-chiffre\"> 1 mois</span> ; <span class=\"kw-chiffre\">&gt; 15 %</span> /<span class=\"kw-chiffre\"> 6 mois</span></td></tr>\n<tr><td><span class=\"kw-chiffre\">IOTF 17 &lt; IMC &lt; IOTF 18,5</span></td><td><span class=\"kw-chiffre\">IMC ≤ IOTF 17</span></td></tr>\n<tr><td>Poids <span class=\"kw-chiffre\">2–3 couloirs</span> sous le couloir habituel</td><td>Poids <span class=\"kw-chiffre\">≥ 3 couloirs</span> en dessous ; <span class=\"kw-clinique\">infléchissement statural</span> (perte <span class=\"kw-chiffre\">≥ 1</span> couloir de taille)</td></tr>\n</tbody>\n</table>\n<div class=\"callout callout-warn\">⚠️ <strong>Un seul <span class=\"kw-def\">critère de</span> dénutrition sévère prime</strong> sur plusieurs <span class=\"kw-def\">critères de</span> dénutrition modérée.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la dénutrition chez l’adulte (< 70 ans)","contenu":"<p>Diagnostic <strong><span class=\"kw-def\">HAS 2019</span></strong>, exclusivement <strong>clinique (sans biologie)</strong> : <strong><span class=\"kw-chiffre\">≥ 1</span> critère phénotypique</strong> ET <strong>≥ 1 critère étiologique</strong>.</p>\n<h4 class=\"kw-def\">Critères phénotypiques (1 seul suffit)</h4>\n<ul>\n<li>Perte de poids <span class=\"kw-chiffre\">≥ 5 % en 1 mois</span>, <span class=\"kw-chiffre\">≥ 10 % en 6 mois</span>, ou <span class=\"kw-chiffre\">≥ 10 %</span> <span class=\"kw-bio\">vs</span> poids habituel avant la maladie.</li>\n<li><span class=\"kw-chiffre\">IMC &lt; 18,5</span>.</li>\n<li><span class=\"kw-ttt\">Réduction</span> quantifiée de la <span class=\"kw-clinique\">masse et/ou de la fonction musculaire</span> : <span class=\"kw-clinique\">force de préhension</span> (hand grip) <span class=\"kw-chiffre\">&lt; 26 kg</span> (homme) / <span class=\"kw-chiffre\">&lt; 16 kg</span> (femme) ; <span class=\"kw-clinique\">vitesse de marche</span> sur 4 m <span class=\"kw-chiffre\">&lt; 0,8 m/s</span>.</li>\n</ul>\n<h4 class=\"kw-def\">Critères étiologiques (1 seul suffit)</h4>\n<ul>\n<li><span class=\"kw-clinique\">Réduction des apports</span> <span class=\"kw-chiffre\">≥ 50 % &gt; 1 semaine</span> (ou toute <span class=\"kw-ttt\">réduction</span> <span class=\"kw-chiffre\">&gt; 2 semaines</span>).</li>\n<li><span class=\"kw-etio\">Malabsorption</span> / maldigestion.</li>\n<li><span class=\"kw-etio\">Situation d'agression</span> (pathologie aiguë, chronique ou maligne évolutive).</li>\n</ul>\n<h4 class=\"kw-def\">Gradation (selon le critère le plus sévère)</h4>\n<table >\n<thead><tr><th>Dénutrition modérée</th><th>Dénutrition sévère</th></tr></thead>\n<tbody>\n<tr><td>Perte <span class=\"kw-chiffre\">≥ 5 %</span>/<span class=\"kw-chiffre\">1 mois</span> ; <span class=\"kw-chiffre\">≥ 10 %</span>/<span class=\"kw-chiffre\">6 mois</span> ; <span class=\"kw-chiffre\">≥ 10 %</span> <span class=\"kw-bio\">vs</span> habituel</td><td>Perte <span class=\"kw-chiffre\">&gt; 10 %</span>/<span class=\"kw-chiffre\">1 mois</span> ; <span class=\"kw-chiffre\">&gt; 15 %</span>/<span class=\"kw-chiffre\">6 mois</span> ; <span class=\"kw-chiffre\">≥ 15 %</span> <span class=\"kw-bio\">vs</span> habituel</td></tr>\n<tr><td><span class=\"kw-chiffre\">17 &lt; IMC &lt; 18,5</span></td><td><span class=\"kw-chiffre\">IMC ≤ 17</span></td></tr>\n<tr><td><span class=\"kw-bio\">Albuminémie</span> <span class=\"kw-chiffre\">&gt; 30 et &lt; 35 g/L</span></td><td><span class=\"kw-bio\">Albuminémie</span> <span class=\"kw-chiffre\">≤ 30 g/L</span></td></tr>\n</tbody>\n</table>\n<div class=\"callout callout-warn\">⚠️ Un <span class=\"kw-chiffre\">IMC</span> normal ou élevé <strong>n'exclut pas</strong> une dénutrition. L'<span class=\"kw-bio\">albuminémie</span> seule n'est <strong>plus un <span class=\"kw-def\">critère diagnostique</span></strong> avant <span class=\"kw-chiffre\">70 ans</span>, mais un <strong>marqueur de gravité</strong> (quelle que soit la <span class=\"kw-bio\">CRP</span>).</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","contenu":"<p>Chez la <strong><span class=\"kw-clinique\">personne âgée de plus de 70 ans</span></strong>, le Collège retient <span class=\"kw-clinique\">les</span> critères <strong><span class=\"kw-def\">HAS 2007</span></strong>, qui comportent encore des <strong><span class=\"kw-bio\">critères biologiques</span></strong>. <strong>Un seul critère suffit.</strong></p>\n<h4 class=\"kw-def\">Dénutrition (HAS 2007)</h4>\n<ul>\n<li>Perte de poids <span class=\"kw-chiffre\">≥ 5 % en 1 mois</span> ou <span class=\"kw-chiffre\">≥ 10 % en 6 mois</span>.</li>\n<li><span class=\"kw-chiffre\">IMC &lt; 21</span>.</li>\n<li><strong><span class=\"kw-bio\">Albuminémie</span></strong> <span class=\"kw-chiffre\">&lt; 35 g/L</span>.</li>\n<li><strong><span class=\"kw-def\">MNA</span></strong> global (<em>Mini Nutritional Assessment</em>) <span class=\"kw-chiffre\">&lt; 17</span>.</li>\n</ul>\n<h4 class=\"kw-def\">Dénutrition sévère</h4>\n<ul>\n<li>Perte de poids <span class=\"kw-chiffre\">≥ 10 % en 1 mois</span> ou <span class=\"kw-chiffre\">≥ 15 % en 6 mois</span>.</li>\n<li><span class=\"kw-chiffre\">IMC &lt; 18</span>.</li>\n<li><strong><span class=\"kw-bio\">Albuminémie</span></strong> <span class=\"kw-chiffre\">&lt; 30 g/L</span>.</li>\n</ul>\n<div class=\"callout callout-warn\">⚠️ Seuils <strong>HAS 2007</strong> (tels que présentés par le Collège de Nutrition) : un groupe de travail HAS est en cours pour <strong>redéfinir</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de</span> la personne âgée sur le modèle <span class=\"kw-def\">phénotypique + étiologique</span> de 2019.</div>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-15","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires permettant de qualifier une dénutrition","contenu":"<p>Le diagnostic de dénutrition est <strong>clinique</strong> : avant <span class=\"kw-chiffre\">70 ans</span>, <strong>aucun examen <span class=\"kw-ttt\">biologique</span> n'est un critère phénotypique</strong> (l'<span class=\"kw-bio\">albumine</span> et la <span class=\"kw-bio\">transthyrétine</span> ne sont plus indiquées pour le diagnostic). La biologie garde son intérêt pour l'<strong>étiologie</strong>, la <strong>sévérité</strong> et <span class=\"kw-clinique\">les</span> <strong>complications</strong>.</p>\n<h4 class=\"kw-def\">Examens biologiques</h4>\n<ul>\n<li><strong><span class=\"kw-bio\">Albuminémie</span></strong> : <strong>marqueur de gravité</strong> (quelle que soit la <span class=\"kw-bio\">CRP</span>) ; demi-vie longue (<span class=\"kw-chiffre\">≈ 3 semaines</span>) ; chute en miroir de l'ascension de la <span class=\"kw-bio\">CRP</span>.</li>\n<li><strong><span class=\"kw-bio\">Transthyrétine</span></strong> (préalbumine) : marqueur <strong>pronostique</strong> et d'<strong>efficacité de la renutrition</strong> ; demi-vie courte (<span class=\"kw-chiffre\">≈ 2 jours</span>) ; <span class=\"kw-chiffre\">&lt; 0,15 g/L</span> = bon marqueur de dénutrition ; influencée par l'<span class=\"kw-etio\">insuffisance rénale</span>.</li>\n<li><strong><span class=\"kw-bio\">CRP</span></strong> : un <span class=\"kw-etio\">syndrome inflammatoire</span> est un critère étiologique de dénutrition.</li>\n</ul>\n<h4 class=\"kw-def\">Examens morphologiques (hors routine)</h4>\n<ul>\n<li>Estimation de la <span class=\"kw-clinique\">masse musculaire</span> par <span class=\"kw-imagerie\">imagerie de coupe en L3</span> (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>), <span class=\"kw-imagerie\">DEXA</span> (absorptiométrie biphotonique) ou <span class=\"kw-bio\">impédancemétrie</span>.</li>\n<li>Aide à valider le critère phénotypique mais <strong>non réalisés en routine</strong> à ce but.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la complémentation orale, de la nutrition entérale et parentérale","contenu":"<p>Trois méthodes d'assistance nutritionnelle, choisies selon la <strong>gravité de la dénutrition</strong>, <span class=\"kw-clinique\">les</span> <strong>ingesta</strong> et l'état du <strong>tube digestif</strong> : <strong><span class=\"kw-def\">complémentation orale</span></strong>, <strong><span class=\"kw-def\">nutrition entérale</span></strong> (NE) et <strong><span class=\"kw-def\">nutrition parentérale</span></strong> (NP). Préalable : estimer les ingesta (<strong><span class=\"kw-def\">EVA</span></strong> 0–10) et fixer les cibles caloriques/protéiques.</p>\n<h4 class=\"kw-def\">1. Adaptation et complémentation orale</h4>\n<ul>\n<li>Adapter la <span class=\"kw-clinique\">texture</span> (troubles de déglutition), respecter <span class=\"kw-clinique\">les</span> goûts.</li>\n<li><strong>Enrichir</strong> (matières grasses, glucides, protéines) et <strong>fractionner</strong> (collations).</li>\n<li><strong><span class=\"kw-def\">Compléments nutritionnels oraux</span></strong> (<span class=\"kw-def\">CNO</span>) : denrées inscrites à la <span class=\"kw-def\">LPPR</span>, hyperénergétiques/hyperprotidiques ; <strong>à distance des repas</strong>, <strong><span class=\"kw-chiffre\">≤ 2 unités/jour</span></strong> ; ne se substituent pas aux repas.</li>\n</ul>\n<h4 class=\"kw-def\">2. Nutrition entérale (1ʳᵉ intention)</h4>\n<ul>\n<li>Mélange complet administré dans le <span class=\"kw-clinique\">tube digestif</span> : <span class=\"kw-clinique\">SNG/SNJ</span> ou <span class=\"kw-clinique\">stomie</span> (gastrostomie/jéjunostomie) si durée <span class=\"kw-chiffre\">&gt; 1 mois</span>.</li>\n<li><strong>Préférée</strong> à la NP si <strong>tube digestif fonctionnel</strong> : plus physiologique, effet <strong>trophique</strong> sur la muqueuse (↓ <span class=\"kw-alerte\">translocation bactérienne</span>).</li>\n<li><span class=\"kw-imagerie\">Contrôle radiographique</span> obl<span class=\"kw-chiffre\">iga</span>toire de la 1ʳᵉ pose de SNG ; <span class=\"kw-alerte\">pneumopathie d'inhalation</span> = complication la plus grave (prévention : position proclive 30°, débit progressif).</li>\n</ul>\n<h4 class=\"kw-def\">3. Nutrition parentérale</h4>\n<ul>\n<li>Perfusion IV d'un mélange <span class=\"kw-def\">ternaire</span> (acides aminés, glucose, lipides) par <strong><span class=\"kw-clinique\">voie veineuse centrale</span></strong> (solutés hyperosmolaires) ; statut de <span class=\"kw-ttt\">médicament</span> (AMM).</li>\n<li><strong>Strictement réservée</strong> au tube digestif <strong>non fonctionnel</strong> ou à l'<strong>échec d'une NE</strong> bien conduite.</li>\n<li><strong>Toujours supplémenter</strong> en <span class=\"kw-bio\">vitamines</span> et <span class=\"kw-bio\">oligoéléments</span> (absents des poches industrielles).</li>\n</ul>\n<h4 class=\"kw-def\">Cibles nutritionnelles (adulte)</h4>\n<ul>\n<li>Énergie : <span class=\"kw-chiffre\">30 kcal/kg/j</span> (maintenance), <span class=\"kw-chiffre\">30–40 kcal/kg/j</span> en contexte pathologique.</li>\n<li>Protéines : <span class=\"kw-chiffre\">1 g/kg/j</span>, jusqu'à <span class=\"kw-chiffre\">1,5 g/kg/j</span> si dénutrition.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0},{"id":"249-17","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic et de la prévention du syndrome de renutrition","contenu":"<p>Le <strong><span class=\"kw-def\">syndrome de renutrition inappropriée</span></strong> (<span class=\"kw-def\">SRI</span>, <em>refeeding syndrome</em>) est une <strong>complication métabolique</strong> survenant à la <strong>réintroduction de la nutrition</strong> (orale, entérale OU parentérale) chez des patients <strong>sévèrement dénutris</strong>, généralement dans <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-chiffre\">72 heures</span></strong>. Fréquent sous forme <span class=\"kw-ttt\">biologique</span>, <strong>rare mais potentiellement mortel</strong> sous forme clinique.</p>\n<div class=\"callout callout-danger\">⚠️ <strong>Biologie :</strong> déficit <strong>aigu en <span class=\"kw-bio\">phosphore</span></strong> (<span class=\"kw-alerte\">hypophosphorémie</span>), ± déficit en <span class=\"kw-bio\">potassium</span>, <span class=\"kw-bio\">magnésium</span> et <span class=\"kw-bio\">thiamine (B1)</span>.<br><strong>Clinique (polymorphe) :</strong> <span class=\"kw-alerte\">arythmie</span>, <span class=\"kw-alerte\">insuffisance cardiaque aiguë</span>, <span class=\"kw-clinique\">syncope</span> ; signes <span class=\"kw-clinique\">neurologiques</span> (paresthésies, confusion, <span class=\"kw-alerte\">convulsions</span>) ; <span class=\"kw-alerte\">insuffisance respiratoire</span> ; <span class=\"kw-clinique\">rhabdomyolyse</span>.</div>\n<h4 class=\"kw-def\">Identifier le haut risque — critères NICE</h4>\n<p>Haut risque = <strong>1 <span class=\"kw-def\">critère majeur</span></strong> OU <strong>2 <span class=\"kw-def\">critères mineurs</span></strong> :</p>\n<ul>\n<li><strong>Majeurs</strong> : <span class=\"kw-chiffre\">IMC &lt; 16</span> ; perte de poids <span class=\"kw-chiffre\">&gt; 15 % en 3–6 mois</span> ; <span class=\"kw-clinique\">jeûne &gt; 10 jours</span> ; <span class=\"kw-bio\">phosphore/potassium/magnésium</span> bas avant renutrition.</li>\n<li><strong>Mineurs</strong> : <span class=\"kw-chiffre\">IMC &lt; 18,5</span> ; perte de poids <span class=\"kw-chiffre\">10–15 %</span> ; <span class=\"kw-clinique\">jeûne 5–10 jours</span> ; <span class=\"kw-etio\">alcoolisme</span>, <span class=\"kw-ttt\">insuline</span>, <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">diurétiques</span>, antiacides.</li>\n</ul>\n<h4 class=\"kw-def\">Prévention</h4>\n<ul>\n<li><strong>Supplémentation systématique en <span class=\"kw-bio\">phosphore</span></strong> avant et pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 jours</span> suivant le début de la renutrition ; ajouter <strong><span class=\"kw-bio\">thiamine (B1)</span></strong>.</li>\n<li><strong>Renutrition progressive</strong> : cible initiale <span class=\"kw-chiffre\">≈ 10 kcal/kg/j</span>, augmentée par paliers de <span class=\"kw-chiffre\">10 kcal/kg</span> selon la tolérance.</li>\n<li><strong><span class=\"kw-def\">Surveillance</span> de la <span class=\"kw-bio\">phosphorémie</span></strong> avant et durant <span class=\"kw-clinique\">les</span> premiers jours ; toute nutrition artificielle est <strong>débutée à l'hôpital</strong>.</li>\n</ul>\n<p class=\"obj-source\"><em>Complété depuis le Collège.</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"0d2a3a6550d7","n":249,"o":"249-1","u":"Diagnostic positif","t":"Savoir évaluer le comportement alimentaire","q":"Quelle démarche d'évaluation doit-on adopter face à un comportement alimentaire à évaluer ?","a":"<p>La démarche d'évaluation d'un comportement alimentaire comprend :</p><ul><li>La recherche d'un <strong>trouble de l'humeur</strong> (ex: dépression).</li><li>La recherche d'une <strong>pathologie chronique</strong> (ex: maladie inflammatoire, cancer).</li><li>Il est possible de faire tenir un <strong>carnet alimentaire</strong> pendant une semaine (cette option est facultative).</li></ul>"},{"i":"22631c80d500","n":249,"o":"249-1","u":"Diagnostic positif","t":"Savoir évaluer le comportement alimentaire","q":"Quelles sont les principales anomalies de la relation à l'alimentation identifiées dans le contexte des modifications thérapeutiques du mode de vie ?","a":"<p>Les principales anomalies de la relation à l'alimentation sont :</p><ul><li>La <strong>tachyphagie</strong> (manger vite).</li><li>L'<strong>hyperphagie prandiale</strong>.</li><li>Les <strong>prises extraprandiales</strong>.</li><li>L'<strong>impulsivité alimentaire</strong>.</li><li>La <strong>restriction cognitive</strong> (contrôle mental des prises se substituant aux signaux physiologiques).</li></ul><p>Ces situations sont souvent associées à l'excès pondéral.</p>"},{"i":"292b61b6363b","n":249,"o":"249-1","u":"Diagnostic positif","t":"Savoir évaluer le comportement alimentaire","q":"Comment les signaux intéroceptifs de faim et de rassasiement sont-ils régulés physiologiquement ?","a":"<p>Ces signaux sont régulés comme suit :</p><ul><li>La <strong>faim</strong> est une sensation physique (contraction de la musculature gastrique) déclenchée par l'<strong>hypothalamus</strong>.</li><li>Le <strong>rassasiement</strong> est l'extinction du signal de faim, sans nouveau signal physique.</li><li>La <strong>satiété</strong> est l'absence de faim, période entre le rassasiement et la faim suivante.</li></ul>"},{"i":"9f0f2de2b157","n":249,"o":"249-1","u":"Diagnostic positif","t":"Savoir évaluer le comportement alimentaire","q":"Quels sont les facteurs connus pour perturber les signaux physiologiques de faim et de rassasiement ?","a":"<p>Les signaux physiologiques de faim et de rassasiement peuvent être perturbés par :</p><ul><li>L'<strong>environnement familial et culturel</strong>.</li><li>L'<strong>inflammation</strong>, notamment de par le rôle de l'<strong>IL-1</strong> et du <strong>TNF-α</strong>.</li></ul>"},{"i":"3af353c89c36","n":249,"o":"249-11","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Comment l'hypercatabolisme protéique contribue-t-il à la physiopathologie de la dénutrition et quelles en sont les conséquences principales au niveau musculaire ?","a":"<p>L'hypercatabolisme protéique en cas de dénutrition conduit à une <strong>sarcopénie</strong>, caractérisée par une diminution de la masse, de la force et de la performance musculaire. Cette sarcopénie entraîne une perte d'autonomie, une diminution de la vitesse de marche et de préhension, et un risque accru de <strong>chutes</strong>. La perte d'environ 50% de la masse musculaire est associée au décès.</p>"},{"i":"5bb226ecb90b","n":249,"o":"249-11","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les conséquences pronostiques globales de la dénutrition ?","a":"<p>La dénutrition est un <strong>facteur indépendant de morbi-mortalité</strong>. Elle entraîne une augmentation de la durée de séjour hospitalier, une augmentation du nombre de prescriptions (notamment d'antibiotiques) et une <strong>augmentation des coûts d'hospitalisation</strong>.</p>"},{"i":"5e237734cb69","n":249,"o":"249-11","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quels sont les impacts de la dénutrition sur le système digestif et l'immunité ?","a":"<ul><li><strong>Muscles lisses digestifs</strong> : La dénutrition peut conduire à un <strong>RGO</strong> (reflux gastro-œsophagien), un retard de vidange gastrique et une constipation.</li><li><strong>Tube digestif</strong> : Elle provoque une <strong>atrophie entérocytaire</strong>, réduisant l'absorption intestinale et favorisant la <strong>translocation bactérienne</strong>, avec un risque de sepsis à BGN (bacilles Gram négatif) et de lâchage de sutures.</li><li><strong>Immunité</strong> : La dénutrition entraîne une <strong>lymphopénie</strong> (moins de 1500/mm³) et une <strong>immunodépression</strong>, augmentant le risque infectieux par 5.</li></ul>"},{"i":"cacfabfe8425","n":249,"o":"249-11","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les conséquences de la dénutrition sur la peau, la cicatrisation, le neuro-cognitif et les os ?","a":"<ul><li><strong>Peau et cicatrisation</strong> : Elle multiplie par 4 le risque d'<strong>escarres</strong>, retarde la cicatrisation et peut entraîner un lâchage de sutures.</li><li><strong>Neuro-cognitif</strong> : Chez l'enfant, elle provoque un <strong>retard des acquisitions</strong>. Chez le sujet âgé, elle est associée à l'<strong>apathie</strong>, la dépression et le <strong>syndrome de glissement</strong>.</li><li><strong>Os</strong> : La dénutrition peut entraîner une <strong>ostéoporose</strong> chez l'adulte et un <strong>retard de croissance staturale</strong> chez l'enfant.</li></ul>"},{"i":"db28b4fe0e68","n":249,"o":"249-11","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les conséquences de la dénutrition sur les systèmes respiratoires et cardiaques ?","a":"<ul><li><strong>Muscles respiratoires</strong> : La dénutrition augmente le risque d'<strong>infections pulmonaires</strong>, aggrave une insuffisance respiratoire préexistante et rend le <strong>sevrage ventilatoire difficile</strong>.</li><li><strong>Muscle cardiaque</strong> : Elle entraîne une diminution de la masse et de la contractilité cardiaque, ce qui aggrave l'<strong>insuffisance cardiaque</strong> et peut provoquer un <strong>OAP</strong> (œdème aigu du poumon) en cas de perfusion excessive.</li></ul>"},{"i":"016c32e829ee","n":249,"o":"249-12","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","q":"Quelle est la règle en présence à la fois de critères de dénutrition modérée et de dénutrition sévère chez l'enfant ?","a":"<p>Un <strong>seul critère de dénutrition sévère prime</strong> sur plusieurs critères de dénutrition modérée, classant ainsi la dénutrition comme sévère.</p>"},{"i":"0d55faf16545","n":249,"o":"249-12","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","q":"Comment différencier une dénutrition modérée d'une dénutrition sévère chez l'enfant selon les critères de perte de poids ?","a":"<ul><li><strong>Dénutrition modérée</strong> : Perte de poids <strong>≥ 5 % et ≤ 10 %</strong> en 1 mois ; ou <strong>≥ 10 % et ≤ 15 %</strong> en 6 mois.</li><li><strong>Dénutrition sévère</strong> : Perte de poids <strong>> 10 %</strong> en 1 mois ; ou <strong>> 15 %</strong> en 6 mois.</li></ul>"},{"i":"253c55dd594b","n":249,"o":"249-12","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","q":"Comment différencier une dénutrition modérée d'une dénutrition sévère chez l'enfant selon les critères d'IMC et de poids par rapport aux couloirs de croissance ?","a":"<ul><li><strong>Dénutrition modérée</strong> : <strong>IOTF 17 < IMC < IOTF 18,5</strong> ; ou poids <strong>2–3 couloirs sous le couloir habituel</strong>.</li><li><strong>Dénutrition sévère</strong> : <strong>IMC ≤ IOTF 17</strong> ; ou poids <strong>≥ 3 couloirs en dessous</strong> du couloir habituel, avec un infléchissement statural (perte ≥ 1 couloir de taille).</li></ul>"},{"i":"361604fed146","n":249,"o":"249-12","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","q":"Quels sont les critères étiologiques à prendre en compte pour le diagnostic de dénutrition chez l'enfant ?","a":"<p>Un seul de ces critères étiologiques est suffisant :</p><ul><li>Une <strong>réduction de la prise alimentaire ≥ 50 % pendant plus d'une semaine</strong>, ou toute réduction de la prise alimentaire de plus de deux semaines.</li><li>Une <strong>malabsorption / maldigestion</strong>.</li><li>Une <strong>situation d'agression</strong> (pathologie aiguë, chronique évolutive ou maligne évolutive).</li></ul>"},{"i":"c5c8e026e081","n":249,"o":"249-12","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","q":"Quels sont les critères phénotypiques permettant de diagnostiquer une dénutrition chez l'enfant ?","a":"<p>Un seul de ces critères phénotypiques est suffisant :</p><ul><li>Une <strong>perte de poids</strong> de <strong>≥ 5 % en 1 mois</strong>, <strong>≥ 10 % en 6 mois</strong>, ou <strong>≥ 10 %</strong> par rapport au poids habituel avant la maladie.</li><li>Un <strong>IMC < courbe IOTF 18,5</strong>.</li><li>Une <strong>stagnation pondérale</strong> aboutissant à un poids <strong>≥ 2 couloirs sous le couloir habituel</strong>.</li><li>Une <strong>réduction de la masse et/ou de la fonction musculaire</strong>.</li></ul>"},{"i":"d6e7a7e23965","n":249,"o":"249-12","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’enfant","q":"Selon la HAS 2019, quel est le principe général du diagnostic de dénutrition chez l'enfant ?","a":"<p>Selon la HAS 2019, le diagnostic de dénutrition chez l'enfant est <strong>exclusivement clinique</strong> et associe <strong>au moins un critère phénotypique ET au moins un critère étiologique</strong>.</p>"},{"i":"59d016a2d4b5","n":249,"o":"249-13","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’adulte (< 70 ans)","q":"Quelle est l'importance de l'albuminémie dans le diagnostic et la gradation de la dénutrition chez l'adulte de moins de 70 ans ?","a":"<p>Chez l'adulte de moins de 70 ans, l'<strong>albuminémie seule n'est plus un critère diagnostique</strong> de dénutrition (quelle que soit la CRP). Elle reste un <strong>marqueur de gravité</strong> :</p><ul><li><strong>Dénutrition modérée</strong> : albuminémie &gt; 30 et &lt; 35 g/L.</li><li><strong>Dénutrition sévère</strong> : albuminémie ≤ 30 g/L.</li></ul>"},{"i":"8555814fecb9","n":249,"o":"249-13","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’adulte (< 70 ans)","q":"Quels sont les critères étiologiques de la dénutrition chez l'adulte de moins de 70 ans ?","a":"<p>Les critères étiologiques (un seul suffit) de la dénutrition chez l'adulte de moins de 70 ans sont :</p><ul><li>Une <strong>réduction des apports</strong> : <ul><li>≥ 50 % pendant plus de 1 semaine, OU</li><li>Toute réduction des apports pendant plus de 2 semaines.</li></ul></li><li>Une <strong>malabsorption / maldigestion</strong>.</li><li>Une <strong>situation d'agression</strong> (pathologie aiguë, chronique ou maligne évolutive).</li></ul>"},{"i":"a33d8ccb68f6","n":249,"o":"249-13","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’adulte (< 70 ans)","q":"Comment différencier une dénutrition modérée d'une dénutrition sévère chez l'adulte de moins de 70 ans, sur les critères de perte de poids et d'IMC ?","a":"<p>La gradation de la dénutrition chez l'adulte de moins de 70 ans est la suivante :</p><ul><li><strong>Dénutrition modérée</strong> :<ul><li>Perte de poids : ≥ 5 % / 1 mois ; ≥ 10 % / 6 mois ; ≥ 10 % vs habituel.</li><li>IMC : entre 17 et 18,5 kg/m².</li></ul></li><li><strong>Dénutrition sévère</strong> :<ul><li>Perte de poids : &gt; 10 % / 1 mois ; &gt; 15 % / 6 mois ; ≥ 15 % vs habituel.</li><li>IMC : ≤ 17 kg/m².</li></ul></li></ul>"},{"i":"b9fe3ed37e04","n":249,"o":"249-13","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’adulte (< 70 ans)","q":"Quels sont les critères phénotypiques de la dénutrition chez l'adulte de moins de 70 ans ?","a":"<p>Les critères phénotypiques (un seul suffit) de la dénutrition chez l'adulte de moins de 70 ans sont :</p><ul><li>Une <strong>perte de poids</strong> : <ul><li>≥ 5 % en 1 mois, OU</li><li>≥ 10 % en 6 mois, OU</li><li>≥ 10 % par rapport au poids habituel avant la maladie.</li></ul></li><li>Un <strong>IMC &lt; 18,5 kg/m²</strong>.</li><li>Une <strong>réduction quantifiée de la masse et/ou de la fonction musculaire</strong> : <ul><li>Force de préhension (hand grip) : &lt; 26 kg chez l'homme, &lt; 16 kg chez la femme.</li><li>Vitesse de marche sur 4 m : &lt; 0,8 m/s.</li></ul></li></ul>"},{"i":"f047ff1ab7d9","n":249,"o":"249-13","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l’adulte (< 70 ans)","q":"Comment est défini le diagnostic de dénutrition chez l'adulte de moins de 70 ans, selon la HAS 2019 ?","a":"<p>Selon la HAS 2019, le diagnostic de dénutrition chez l'adulte de moins de 70 ans est <strong>exclusivement clinique</strong> et repose sur la présence d'<strong>au moins un critère phénotypique ET au moins un critère étiologique</strong>.</p>"},{"i":"3f3f923b6b0a","n":249,"o":"249-14","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","q":"Selon les critères HAS 2007, quels sont les critères diagnostiques de dénutrition chez la personne âgée de plus de 70 ans ?","a":"<p>Chez la personne âgée de plus de 70 ans, un seul critère suffit pour poser le diagnostic de dénutrition selon les critères HAS 2007 :</p><ul><li>Une <strong>perte de poids ≥ 5 % en 1 mois</strong> ou <strong>≥ 10 % en 6 mois</strong>.</li><li>Un <strong>IMC < 21 kg/m²</strong>.</li><li>Une <strong>albuminémie < 35 g/L</strong>.</li><li>Un score au <strong>MNA global (Mini Nutritional Assessment) < 17</strong>.</li></ul>"},{"i":"b6468e0fe8d5","n":249,"o":"249-14","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","q":"Selon les critères HAS 2007, quels sont les seuils pour définir une dénutrition sévère chez la personne âgée de plus de 70 ans ?","a":"<p>Selon les critères HAS 2007, les seuils pour la dénutrition sévère chez la personne âgée de plus de 70 ans sont :</p><ul><li>Une <strong>perte de poids ≥ 10 % en 1 mois</strong> ou <strong>≥ 15 % en 6 mois</strong>.</li><li>Un <strong>IMC < 18 kg/m²</strong>.</li><li>Une <strong>albuminémie < 30 g/L</strong>.</li></ul>"}]};